  1	"use client";
  2	
  3	import React, { useState, useEffect, useCallback } from "react";
  4	import Link from "next/link";
  5	import {
  6	  Search, Film, Users, Globe, MessageSquare, Camera, Clapperboard,
  7	  Tv, Star, ChevronRight, Loader2, UserCheck, Megaphone, Sparkles, HelpCircle
  8	} from "lucide-react";
  9	import { globalSearch } from "@/actions/search";
 10	import { DEFAULT_AVATAR } from "@/lib/avatars";
 11	import GlassCard from "@/components/shared/GlassCard";
 12	import AISearchBar from "@/components/ai/AISearchBar";
 13	import AIMovieCard from "@/components/ai/AIMovieCard";
 14	import { motion, AnimatePresence } from "framer-motion";
 15	
 16	const CATEGORIES = [
 17	  { id: "all", label: "All", icon: Search },
 18	  { id: "movies", label: "Movies", icon: Film },
 19	  { id: "tv", label: "TV Shows", icon: Tv },
 20	  { id: "cast", label: "Cast", icon: Camera },
 21	  { id: "crew", label: "Crew", icon: Clapperboard },
 22	  { id: "people", label: "Critics", icon: Users },
 23	  { id: "communities", label: "Communities", icon: Globe },
 24	  { id: "posts", label: "Discussions", icon: MessageSquare },
 25	];
 26	
 27	export default function SearchPage() {
 28	  const [query, setQuery] = useState("");
 29	  const [category, setCategory] = useState("all");
 30	  const [results, setResults] = useState<any>(null);
 31	  const [loading, setLoading] = useState(false);
 32	  const [searched, setSearched] = useState(false);
 33	
 34	  // AI Semantic Search states
 35	  const [searchMode, setSearchMode] = useState<"traditional" | "ai">("ai");
 36	  const [aiResults, setAiResults] = useState<any>(null);
 37	  const [aiLoading, setAiLoading] = useState(false);
 38	  const [aiError, setAiError] = useState("");
 39	
 40	  const doSearch = useCallback(async (q: string, cat: string) => {
 41	    if (q.trim().length < 2) {
 42	      setResults(null);
 43	      setSearched(false);
 44	      return;
 45	    }
 46	    setLoading(true);
 47	    const res = await globalSearch(q, cat);
 48	    if (res.success) {
 49	      setResults(res.results);
 50	      setSearched(true);
 51	    }
 52	    setLoading(false);
 53	  }, []);
 54	
 55	  const handleSearchSubmit = async (q: string, mode: "traditional" | "ai") => {
 56	    setSearchMode(mode);
 57	    setQuery(q);
 58	    if (mode === "traditional") {
 59	      doSearch(q, category);
 60	    } else {
 61	      setAiLoading(true);
 62	      setAiResults(null);
 63	      setAiError("");
 64	      try {
 65	        const res = await fetch("/api/ai/search", {
 66	          method: "POST",
 67	          headers: { "Content-Type": "application/json" },
 68	          body: JSON.stringify({ query: q })
 69	        });
 70	        const data = await res.json().catch(() => null);
 71	        if (res.ok) {
 72	          setAiResults(data);
 73	        } else {
 74	          setAiError(data?.error || "Semantic search is temporarily unavailable. Please try again.");
 75	        }
 76	      } catch (err) {
 77	        console.error(err);
 78	        setAiError("Could not connect to semantic search. Check your connection and try again.");
 79	      } finally {
 80	        setAiLoading(false);
 81	      }
 82	    }
 83	  };
 84	
 85	  useEffect(() => {
 86	    if (searchMode === "traditional") {
 87	      const timer = setTimeout(() => doSearch(query, category), 500);
 88	      return () => clearTimeout(timer);
 89	    }
 90	  }, [query, category, doSearch, searchMode]);
 91	
 92	  const imgUrl = (path: string | null | undefined, size = "w300") =>
 93	    path ? `/api/tmdb/img?path=/t/p/${size}${path}` : null;
 94	
 95	  return (
 96	    <div className="max-w-6xl mx-auto px-4 py-6 min-h-screen">
 97	
 98	      {/* Header */}
 99	      <div className="space-y-1 mb-8">
100	        <h1 className="font-display font-extrabold text-3xl md:text-4xl text-white flex items-center gap-3">
101	          <span className="inline-flex items-center justify-center w-10 h-10 rounded-xl bg-gradient-to-br from-brand-blue to-brand-purple shadow-lg">
102	            <Search className="w-5 h-5 text-white" />
103	          </span>
104	          Global Search
105	        </h1>
106	        <p className="text-sm text-slate-400 pl-1">Discover movies, cast, crew, critics, communities and discussions.</p>
107	      </div>
108	
109	      {/* Search Bar */}
110	      <div className="mb-8">
111	        <AISearchBar onSearch={handleSearchSubmit} isLoading={aiLoading || loading} />
112	      </div>
113	
114	      {aiError && (
115	        <p role="alert" className="mb-6 rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-3 text-sm text-red-200">
116	          {aiError}
117	        </p>
118	      )}
119	
120	      {/* Category Tabs (only for Traditional search) */}
121	      {searchMode === "traditional" && (
122	        <div className="flex items-center gap-2 mb-8 overflow-x-auto pb-2 no-scrollbar">
123	          {CATEGORIES.map((cat) => {
124	            const Icon = cat.icon;
125	            const active = category === cat.id;
126	            return (
127	              <button
128	                key={cat.id}
129	                onClick={() => setCategory(cat.id)}
130	                className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap border transition-all ${
131	                  active
132	                    ? "bg-gradient-to-r from-brand-blue/20 to-brand-purple/20 border-brand-purple/50 text-white shadow"
133	                    : "bg-white/5 border-white/10 text-slate-400 hover:text-white hover:bg-white/10"
134	                }`}

